/**
 * How you get at a save, rather than what is in one.
 *
 * `values` reads typed scalars out of a decoded save root, tolerating the shapes the format
 * actually uses; `path` says where the file lives on each platform. Neither knows anything about
 * The Tower — both would be the same for any NRBF save — which is why neither is a subject.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    —
 * depends    src/save/access/path, src/save/access/values
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
export * from './values'
export * from './path'
